from http.server import BaseHTTPRequestHandler, HTTPServer

def today_ms(hour):
    import datetime
    now = datetime.datetime.now(datetime.timezone.utc)
    dt = now.replace(hour=hour, minute=0, second=0, microsecond=0)
    return int(dt.timestamp() * 1000)

